<script setup>import{Link,router}from'@inertiajs/vue3';import AdminLayout from'../../../Layouts/AdminLayout.vue';import Pagination from'../../../Components/Pagination.vue';defineProps({services:Object,counts:Object});const trash=s=>confirm('Move service to Trash?')&&router.delete(`/admin/services/${s.slug}`),restore=s=>router.post(`/admin/services/${s.id}/restore`);</script><template><AdminLayout><div class="flex justify-between"><div><p class="section-kicker">Services</p><h1 class="section-title">Service catalogue</h1></div><Link href="/admin/services/create" class="btn-primary">Add service</Link></div><div class="card mt-6 overflow-x-auto"><table class="admin-table"><thead><tr><th>Service</th><th>Category</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="s in services.data" :key="s.id"><td><b>{{s.name}}</b></td><td>{{s.category?.name}}</td><td class="capitalize">{{s.status}}</td><td><div class="flex gap-2"><Link v-if="!s.deleted_at" :href="`/admin/services/${s.slug}/edit`" class="font-bold text-prinx-600">Edit</Link><button v-if="!s.deleted_at" class="font-bold text-red-600" @click="trash(s)">Trash</button><button v-else class="font-bold text-emerald-600" @click="restore(s)">Restore</button></div></td></tr></tbody></table></div><Pagination :links="services.links"/></AdminLayout></template>
